const rows = $input.all();
const newRows = rows.filter(item =>
  (item.json.STATUS || '').toString().trim().toLowerCase() === 'new'
);
if (newRows.length === 0) {
  throw new Error('No ideas with STATUS = "New" found in the sheet.');
}
const displayRows = newRows.slice(0, 10);
const topicList = displayRows
  .map((item, i) => `${i + 1}. ${item.json.TOPIC || '(no topic)'}`)
  .join('\n');
const allRows = displayRows.map(r => r.json);
return [{ json: { topicList, allRows: JSON.stringify(allRows), count: displayRows.length } }];

const selection = parseInt($json['CASE NUMBER'], 10);
const allRows = JSON.parse($('Aggregate Topics').item.json.allRows);
if (!selection || selection < 1 || selection > allRows.length) {
  throw new Error(`Invalid selection "${selection}". Enter 1–${allRows.length}.`);
}
const row = allRows[selection - 1];

const ts   = new Date().toISOString().replace(/[^0-9]/g, '').substring(0, 12);
const slug = (row.TOPIC || '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').substring(0, 45) + '_' + ts;
const projectDir = '/Users/jneal/n8n_projects/' + slug;

return [{
  json: {
    topic:         row.TOPIC           || '',
    audience:      'curious history fans, conspiracy-adjacent adults 25-45',
    runtime:       20,
    angle:         row.ANGLE          || '',
    keyEvidence:   row.KEY_EVIDENCE   || '',
    keyResearchers:row.KEY_RESEARCHERS|| '',
    relatedVideo:  row.RELATED_VIDEO  || 'N/A',
    hookStyle:     row.HOOK_STYLE     || 'contradiction',
    toneDial:      parseInt(row.TONE_DIAL, 10) || 7,
    slug,
    projectDir
  }
}];

const fs   = require('fs');
const path = require('path');
const inp  = $input.first().json;
const dirs = ['scripts', 'audio', 'images', 'videos', 'clips', 'music', 'sfx'];
fs.mkdirSync(inp.projectDir, { recursive: true });
for (const d of dirs) {
  fs.mkdirSync(path.join(inp.projectDir, d), { recursive: true });
}
console.log('Project directory created: ' + inp.projectDir);
return [{ json: inp }];

const fs  = require('fs');
const inp = $input.first().json;
const sys = fs.readFileSync('/Users/jneal/n8n_projects/ruins_untold_system_prompts/research_agent.md', 'utf-8');
const userInput = JSON.stringify({ topic: inp.topic, audience: inp.audience, runtime: inp.runtime }, null, 2);
const fullPrompt = sys + '\n\n---\n\nYour input:\n\n' + userInput;
console.log('Research Agent — prompt length: ' + fullPrompt.length);
const res  = await fetch('http://host.docker.internal:3333/generate', {
  method: 'POST', headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ prompt: fullPrompt })
});
const data = await res.json();
if (data.exitCode !== 0) throw new Error('Research Agent failed: ' + data.error);
let raw = data.output.trim();
const m = raw.match(/```(?:json)?\n?([\s\S]*?)```/);
if (m) raw = m[1].trim();
let pkg;
try { pkg = JSON.parse(raw); }
catch (e) {
  const s = raw.indexOf('{'), en = raw.lastIndexOf('}');
  if (s === -1 || en === -1) throw new Error('Cannot parse research package JSON');
  pkg = JSON.parse(raw.substring(s, en + 1));
}
const outPath = inp.projectDir + '/scripts/research_package.json';
fs.writeFileSync(outPath, JSON.stringify(pkg, null, 2), 'utf-8');
console.log('Saved: ' + outPath);
return [{ json: { ...inp, researchPackage: pkg } }];

const fs  = require('fs');
const inp = $input.first().json;
const sys = fs.readFileSync('/Users/jneal/n8n_projects/ruins_untold_system_prompts/script_agent.md', 'utf-8');
const fullPrompt = sys + '\n\n---\n\nYour input (research_package.json):\n\n' + JSON.stringify(inp.researchPackage, null, 2);
console.log('Script Agent — prompt length: ' + fullPrompt.length);
const res  = await fetch('http://host.docker.internal:3333/generate', {
  method: 'POST', headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ prompt: fullPrompt })
});
const data = await res.json();
if (data.exitCode !== 0) throw new Error('Script Agent failed: ' + data.error);
const script = data.output.trim();
fs.writeFileSync(inp.projectDir + '/scripts/script.md', script, 'utf-8');
console.log('Script saved (' + script.split(' ').length + ' words)');
return [{ json: { ...inp, scriptContent: script } }];

const fs  = require('fs');
const inp = $input.first().json;
const sys = fs.readFileSync('/Users/jneal/n8n_projects/ruins_untold_system_prompts/voice_agent.md', 'utf-8');
const fullPrompt = sys + '\n\n---\n\nYour input (script.md):\n\n' + inp.scriptContent;
console.log('Voice Agent — prompt length: ' + fullPrompt.length);
const res  = await fetch('http://host.docker.internal:3333/generate', {
  method: 'POST', headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ prompt: fullPrompt })
});
const data = await res.json();
if (data.exitCode !== 0) throw new Error('Voice Agent failed: ' + data.error);
let raw = data.output.trim();
const m = raw.match(/```(?:json)?\n?([\s\S]*?)```/);
if (m) raw = m[1].trim();
let pkg;
try { pkg = JSON.parse(raw); }
catch (e) {
  const s = raw.indexOf('{'), en = raw.lastIndexOf('}');
  if (s === -1 || en === -1) throw new Error('Cannot parse voice package JSON');
  pkg = JSON.parse(raw.substring(s, en + 1));
}
fs.writeFileSync(inp.projectDir + '/audio/voice_package.json', JSON.stringify(pkg, null, 2), 'utf-8');
console.log('Voice package saved (' + pkg.segments.length + ' segments)');
// Reset TTS chain state
const sd = $getWorkflowStaticData('global');
sd.ruinsVoicePrevIds = [];
return [{ json: { ...inp, voicePackage: pkg } }];

const inp  = $input.first().json;
const segs = inp.voicePackage.segments;
const out  = segs.map((seg, i) => ({
  json: {
    projectDir:  inp.projectDir,
    voiceId:     inp.voicePackage.voice_id,
    model:       inp.voicePackage.model,
    segmentId:   seg.segment_id,
    sequence:    seg.sequence,
    seqPad:      String(seg.sequence).padStart(3, '0'),
    chunkText:   seg.voice_optimized_text,
    isFirstChunk: i === 0
  }
}));
console.log('Extracted ' + out.length + ' voice segments');
return out;

const item       = $input.item.json;
const staticData = $getWorkflowStaticData('global');
const kieInput = {
  dialogue: [{ text: item.chunkText, voice: item.voiceId }],
  stability: 0.5
};
if (!item.isFirstChunk && staticData.ruinsVoicePrevIds && staticData.ruinsVoicePrevIds.length > 0) {
  kieInput.previous_request_ids = staticData.ruinsVoicePrevIds.slice(-3);
}
const kieBody = { model: 'elevenlabs/text-to-dialogue-v3', input: kieInput };
return [{
  json: {
    ...item,
    kieBody:         JSON.stringify(kieBody),
    includedPrevIds: kieInput.previous_request_ids || []
  }
}];

const response  = $input.item.json;
const chunkMeta = $('Prepare TTS Request').item.json;
if (response.code !== 200) {
  throw new Error('Kie.ai createTask failed (seg ' + chunkMeta.segmentId + '): ' + response.msg);
}
return [{ json: { ...chunkMeta, kieTaskId: response.data.taskId } }];

const pollResp   = $input.item.json;
const chunkMeta  = $('Prepare TTS Request').item.json;
const staticData = $getWorkflowStaticData('global');
let resultJson = {};
try { resultJson = JSON.parse(pollResp.data.resultJson || '{}'); } catch(e) {}
const requestId =
  resultJson.request_id     ||
  resultJson.history_item_id||
  resultJson.requestId      ||
  $('Extract Task ID').item.json.kieTaskId;
if (!staticData.ruinsVoicePrevIds) staticData.ruinsVoicePrevIds = [];
staticData.ruinsVoicePrevIds.push(requestId);
if (staticData.ruinsVoicePrevIds.length > 3) {
  staticData.ruinsVoicePrevIds = staticData.ruinsVoicePrevIds.slice(-3);
}
const audioUrl =
  (resultJson.resultUrls || [])[0] ||
  (pollResp.data.resultUrls  || [])[0] ||
  '';
if (!audioUrl) throw new Error('No audio URL for seg ' + chunkMeta.segmentId + '. state=' + pollResp.data.state);
return [{ json: { ...chunkMeta, kieRequestId: requestId, audioUrl } }];

const { execSync } = require('child_process');
const fs   = require('fs');
const inp  = $input.first().json;
const dir  = inp.projectDir + '/audio';

// Collect all segment MP3s in order
const files = fs.readdirSync(dir)
  .filter(f => f.startsWith('seg_') && f.endsWith('.mp3'))
  .sort();

if (files.length === 0) throw new Error('No segment audio files found in ' + dir);
console.log('Concatenating ' + files.length + ' segments...');

const concatTxt = dir + '/concat.txt';
fs.writeFileSync(concatTxt, files.map(f => "file '" + dir + '/' + f + "'").join('\n'), 'utf-8');

const finalPath = dir + '/voiceover_final.mp3';
execSync('ffmpeg -y -f concat -safe 0 -i "' + concatTxt + '" -c copy "' + finalPath + '"', { timeout: 120000 });
console.log('Voiceover final: ' + finalPath);
return [{ json: { ...inp, voiceFinalPath: finalPath } }];
